137:     private void sleepIfRequired(int bytesDown, EffectiveEndpointPolicy policy) throws ConnectException {
138:         int delayCycles = 0;
139:         synchronized (bufferAccountingLock) {
140:             lastReadThreadId = Thread.currentThread().getId();
141:             if (lastReadThreadId == lastWriteThreadId) {
142:                 potentiallyBufferedOutputBytes = 0;
143:             }
144:             potentiallyBufferedInputBytes -= bytesDown;
145:             if (potentiallyBufferedInputBytes < 0) {
146:                 delayCycles = 1 + (-1 * potentiallyBufferedInputBytes)
147:                         / SniffyNetworkConnection.DEFAULT_TCP_WINDOW_SIZE;
148:                 potentiallyBufferedInputBytes = SniffyNetworkConnection.DEFAULT_TCP_WINDOW_SIZE;
149:             }
150:         }
151:         // Policy resolution and sleeping can re-enter instrumentation; never perform them under
152:         // the short cross-direction accounting critical section.
153:         if (delayCycles > 0) checkConnectionAllowed(policy, delayCycles);
154:     }
