374:     static byte[] copyTransferredBytes(ByteBuffer[] buffers, int offset, int length,
375:                                        int[] initialPositions, long transferredBytes) {
376:         int capturedLength = (int) Math.min(transferredBytes, INITIAL_PACKET_CAPTURE_LIMIT);
377:         byte[] bytes = new byte[capturedLength];
378:         int destinationOffset = 0;
379:         for (int i = 0; i < length && destinationOffset < capturedLength; i++) {
380:             ByteBuffer buffer = buffers[offset + i];
381:             int transferred = Math.min(buffer.position() - initialPositions[i], capturedLength - destinationOffset);
382:             if (transferred > 0) {
383:                 ByteBuffer duplicate = buffer.duplicate();
384:                 duplicate.limit(initialPositions[i] + transferred);
385:                 duplicate.position(initialPositions[i]);
386:                 duplicate.get(bytes, destinationOffset, transferred);
387:                 destinationOffset += transferred;
388:             }
389:         }
390:         if (destinationOffset == capturedLength) {
391:             return bytes;
392:         }
393:         byte[] exactBytes = new byte[destinationOffset];
394:         System.arraycopy(bytes, 0, exactBytes, 0, destinationOffset);
395:         return exactBytes;
396:     }
