408:     private static boolean isProxyDecisionComplete(byte[] candidate) {
409:         byte[] connectPrefix = new byte[]{'C', 'O', 'N', 'N', 'E', 'C', 'T', ' '};
410:         int prefixLength = Math.min(candidate.length, connectPrefix.length);
411:         for (int i = 0; i < prefixLength; i++) {
412:             if (candidate[i] != connectPrefix[i]) return true;
413:         }
414:         if (candidate.length < connectPrefix.length) return false;
415:         if (httpHeaderLength(candidate) > 0) return true;
416:         return candidate.length >= INITIAL_PACKET_CAPTURE_LIMIT;
417:     }
