420:         for (int i = 1; i < bytes.length; i++) {
421:             if ('\n' == bytes[i] && '\n' == bytes[i - 1]) return i + 1;
422:             if (i >= 3 && '\r' == bytes[i - 3] && '\n' == bytes[i - 2] &&
423:                     '\r' == bytes[i - 1] && '\n' == bytes[i]) {
424:                 return i + 1;
425:             }
426:         }
427:         return 0;
