179:     private void checkConnectionAllowed(EffectiveEndpointPolicy policy, int numberOfSleepCycles) throws ConnectException {
180: 
181:         if (!SniffyConfiguration.INSTANCE.getSocketFaultInjectionEnabled()) return;
182: 
183:         if (null != policy.address && null != policy.status) {
184:             Integer connectionStatus = policy.status;
185:             if (connectionStatus < 0) {
186:                 if (numberOfSleepCycles > 0 && -1 != connectionStatus) try {
187:                     sleepImpl(-1 * connectionStatus * numberOfSleepCycles);
188:                 } catch (InterruptedException e) {
189:                     Thread.currentThread().interrupt();
190:                 }
191:                 throw new ConnectException(String.format("Connection to %s refused by Sniffy", policy.address));
192:             } else if (numberOfSleepCycles > 0 && connectionStatus > 0) {
193:                 try {
194:                     sleepImpl(connectionStatus * numberOfSleepCycles);
195:                 } catch (InterruptedException e) {
196:                     Thread.currentThread().interrupt();
197:                 }
198:             }
199:         }
200:     }
